"],codeSnippet:"// ShoppingCartContext.js\nimport { createContext, useState, useContext } from 'react';\n\nconst ShoppingCartContext = createContext();\n\nexport function ShoppingCartProvider({ children }) {\n  const [cartItems, setCartItems] = useState([]);\n\n  const addToCart = (product, quantity = 1) => {\n    setCartItems(prevItems => {\n      const existingItem = prevItems.find(item => item.id === product.id);\n      if (existingItem) {\n        return prevItems.map(item =>\n          item.id === product.id\n            ? { ...item, quantity: item.quantity + quantity }\n            : item\n        );\n      }\n      return [...prevItems, { ...product, quantity }];\n    });\n  };\n\n  const removeFromCart = (productId) => {\n    setCartItems(prevItems => \n      prevItems.filter(item => item.id !== productId)\n    );\n  };\n\n  return (\n    <ShoppingCartContext.Provider value={{ \n      cartItems, \n      addToCart, \n      removeFromCart \n    }}>\n      {children}\n    </ShoppingCartContext.Provider>\n  );\n}",architecture:["React Router configuration with 4+ distinct routes/pages","Context API implementation for global state management","Mock JSON server for simulating API endpoints","Unit testing setup with Jest and React Testing Library","Responsive design implementation following Figma mockups"],highlights:["Clean component architecture with proper separation of concerns","Comprehensive unit tests for critical components","Global state management using Context API","Mock API integration for product data","Modern UI design implemented with responsive CSS","Form validation and error handling","Shopping cart persistence","Optimized performance with React best practices"],contributors:["Brian Janes","Brad Ayers"]}].map(((e,t)=>(0,Pe.jsx)(On,{...e},t)))}),Fn=e=>{let{code:t}=e;const n=t.split("\n");return(0,Pe.jsx)("div",{className:"w-full",children:(0,Pe.jsxs)("div",{className:"bg-gray-900 rounded-lg overflow-hidden",children:[(0,Pe.jsxs)("div",{className:"fl